#!/usr/bin/env python3
"""Regenerate test/blake2/vectors.cljk.

The one thing a hash implementation cannot check is itself. These vectors
therefore come from CPython's `hashlib`, which is a binding to the BLAKE2
reference implementation (the `blake2b` in `Modules/_blake2/impl/`) — a
different implementation, in a different language, by different people —
rather than from this library. Same discipline as `io-storj-node`'s
`testdata/gen_vectors.go`, and the reason this file is Python and not nbb:
Node's `crypto` cannot produce a variable-length BLAKE2b digest at all, so
an nbb generator would have had to call *this* library to describe itself.

Two vectors are additionally pinned by hand in the test file as literals
taken from RFC 7693 §A.1 and the BLAKE2 reference `blake2b-kat.json`, so a
hypothetical CPython regression cannot silently move the whole target.

    python3 testdata/gen_vectors.py > test/blake2/vectors.cljk
"""
import hashlib


def h(data: bytes, size: int = 64, key: bytes = b"") -> str:
    return hashlib.blake2b(data, digest_size=size, key=key).hexdigest()


def case(name: str, data: bytes, size: int = 64, key: bytes = b"") -> str:
    return (
        "  {:name %-28s :input %-18s :key %-14s :digest-size %2d\n"
        "   :digest %s}"
        % (
            '"%s"' % name,
            '"%s"' % data.hex() if len(data) <= 8 else '"%s"' % data.hex(),
            '"%s"' % key.hex() if key else "nil",
            size,
            '"%s"' % h(data, size, key),
        )
    )


def main() -> None:
    seq = bytes(range(256))
    cases = []

    # RFC 7693 §A.1 and the empty string: the two values every BLAKE2b
    # implementation is expected to reproduce.
    cases.append(case("rfc7693-abc", b"abc"))
    cases.append(case("empty", b""))

    # Every digest length Filecoin asks for, plus the extremes.
    for size in (1, 4, 20, 32, 48, 64):
        cases.append(case("abc-d%d" % size, b"abc", size))

    # Block boundaries. BLAKE2b compresses 128 bytes at a time, and the
    # final-block flag plus the byte counter are exactly what an off-by-one
    # here gets wrong.
    for n in (1, 63, 64, 127, 128, 129, 255, 256, 257):
        cases.append(case("seq%d" % n, seq[:n]))

    # Keyed mode (RFC 7693 §2.9): the key is hashed as a zero-padded block
    # ahead of the input, which moves the counter — including when the input
    # is empty and the key block is therefore also the last block.
    key = bytes(range(64))
    cases.append(case("keyed-empty", b"", 64, key))
    cases.append(case("keyed-abc", b"abc", 64, key))
    cases.append(case("keyed-seq128", seq[:128], 64, key))
    cases.append(case("keyed-short", seq[:3], 32, bytes(range(16))))

    # Filecoin's two shapes: a 65-byte uncompressed secp256k1 public key
    # hashed to a 20-byte address payload, and a 21-byte (protocol byte ++
    # payload) hashed to a 4-byte checksum.
    pubkey = bytes(
        [4, 148, 2, 250, 195, 126, 100, 50, 164, 22, 163, 160, 202, 84, 38,
         181, 24, 90, 179, 178, 79, 97, 52, 239, 162, 92, 228, 135, 200, 45,
         46, 78, 19, 191, 69, 37, 17, 224, 210, 36, 84, 33, 248, 97, 59, 193,
         13, 114, 250, 33, 102, 102, 169, 108, 59, 193, 57, 32, 211, 255, 35,
         63, 208, 188, 5]
    )
    cases.append(case("fil-secp-payload", pubkey, 20))
    payload = hashlib.blake2b(pubkey, digest_size=20).digest()
    cases.append(case("fil-secp-checksum", bytes([1]) + payload, 4))

    print(";; GENERATED by testdata/gen_vectors.py — do not edit by hand.")
    print(";; Oracle: CPython hashlib (BLAKE2 reference implementation).")
    print(";;")
    print(";; Emitted as source rather than as a data file the tests read:")
    print(";; nbb and the JVM do not agree on how to slurp a relative path, and")
    print(";; a vector table that fails to load is a test suite that passes.")
    print("(ns blake2.vectors)")
    print("")
    print("(def vectors")
    print(" [")
    print("\n".join(cases))
    print(" ])")


if __name__ == "__main__":
    main()
